module D where
import Data.Kind (Type)
import Data.Proxy (Proxy)
class C (a :: Type) where
  type F a (k :: Type) (b :: k) :: k
  type F a k b = b
instance C Int
ok :: Proxy (F Int Bool 'True) -> Proxy 'True
ok = id

